liquid:
{%- assign valid = true -%}
{%- assign matches = false -%}
{%- assign inputs = nil -%}
{%- assign hasInputs = apiEaseParameters | has_key: 'liquidParams' -%}
{%- if hasInputs -%}
  {%- assign inputs = apiEaseParameters.liquidParams -%}
{%- endif -%}
{%- if valid -%}
  {%- assign valid = inputs | has_key: 'title' -%}
{%- endif -%}
{%- if valid -%}
  {%- assign valid = inputs.title | is_type: 'string' -%}
{%- endif -%}
{%- if valid -%}
  {%- assign valid = inputs | has_key: 'prefix' -%}
{%- endif -%}
{%- if valid -%}
  {%- assign valid = inputs.prefix | is_type: 'string' -%}
{%- endif -%}
{%- if valid -%}
  {%- if inputs.prefix == '' -%}{%- assign valid = false -%}{%- endif -%}
{%- endif -%}
{%- if valid -%}
  {%- assign prefixLength = inputs.prefix | size -%}
  {%- assign titlePrefix = inputs.title | slice: 0, prefixLength -%}
  {%- if titlePrefix == inputs.prefix -%}{%- assign matches = true -%}{%- endif -%}
{%- endif -%}
{%- if valid -%}
{"success":true,"matches":{{ matches | json }},"error":null}
{%- else -%}
{"success":false,"matches":false,"error":"title must be a string and prefix must be a nonempty string; both fields are required."}
{%- endif -%}
